#include <bits/stdc++.h>
using namespace std;
const int INF = 0x3f3f3f3f;
const int MAX_M = 2000015;
const int MAX_N = 5775;
int n, m, c, d, k;

inline int input() {
    int x = 0, sign = 1;
    char c = getchar_unlocked();
    while (c < '0' || c > '9') { if (c == '-') sign = -1; c = getchar_unlocked(); }
    while (c >= '0' && c <= '9') { x = x * 10 + c - '0'; c = getchar_unlocked(); }
    return x * sign;
}

struct Edge {
    int dest, next_edge, capacity, flow, weight;
} graph[MAX_M];

int adj[MAX_N], edge_count;
int prev_edge[MAX_N], dist[MAX_N];
bool in_queue[MAX_N];
int node_count;

void reset(int total_nodes) {
    node_count = total_nodes;
    edge_count = 0;
    memset(adj, -1, sizeof(adj));
}

void connect(int from, int to, int cap, int cost) {
    graph[edge_count] = {to, adj[from], cap, 0, cost};
    adj[from] = edge_count++;
    graph[edge_count] = {from, adj[to], 0, 0, -cost};
    adj[to] = edge_count++;
}

bool find_path(int source, int sink) {
    queue<int> q;
    fill(dist, dist + node_count, INF);
    fill(in_queue, in_queue + node_count, false);
    fill(prev_edge, prev_edge + node_count, -1);
    dist[source] = 0;
    in_queue[source] = true;
    q.push(source);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = false;
        for (int i = adj[u]; ~i; i = graph[i].next_edge) {
            int v = graph[i].dest;
            if (graph[i].capacity > graph[i].flow && dist[v] > dist[u] + graph[i].weight) {
                dist[v] = dist[u] + graph[i].weight;
                prev_edge[v] = i;
                if (!in_queue[v]) {
                    in_queue[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return prev_edge[sink] != -1;
}

int compute_min_cost_flow(int src, int dst, int &total_cost) {
    int total_flow = 0;
    total_cost = 0;
    while (find_path(src, dst)) {
        int bottleneck = INF;
        for (int i = prev_edge[dst]; ~i; i = prev_edge[graph[i^1].dest])
            bottleneck = min(bottleneck, graph[i].capacity - graph[i].flow);
        for (int i = prev_edge[dst]; ~i; i = prev_edge[graph[i^1].dest]) {
            graph[i].flow += bottleneck;
            graph[i^1].flow -= bottleneck;
            total_cost += graph[i].weight * bottleneck;
        }
        total_flow += bottleneck;
    }
    return total_flow;
}

int encode(int row, int col) { return (row-1)*50 + col; }

int main() {
    int source = 101*55, sink = source + 1;
    n = input(), m = input(), k = input(), c = input(), d = input();
    int val;
    reset(sink + 1);
    for (int i = 1; i <= k; i++) {
        val = input();
        connect(source, val, 1, 0);
    }
    for (int col = 1; col <= 50; col++) {
        for (int row = 1; row <= 103; row++) {
            int a = encode(row, col), b = encode(row+1, col);
            connect(a, b, INF, c);
        }
    }
    for (int i = 0; i < 102; i++) {
        int node = i*50 + 1;
        connect(node, sink, INF, 0);
    }
    for (int i = 1; i <= m; i++) {
        int u = input(), v = input();
        for (int row = 1; row <= 102; row++) {
            int a = encode(row, u), a_next = encode(row+1, u);
            int b_next = encode(row+1, v), b = encode(row, v);
            for (int layer = 0; layer < 50; layer++) {
                int cost = d*(layer*2+1) + c;
                connect(a, b_next, 1, cost);
                connect(b, a_next, 1, cost);
            }
        }
    }
    int total_cost = 0;
    compute_min_cost_flow(source, sink, total_cost);
    printf("%d\n", total_cost);
    return 0;
}
